// === Tab: mySketch ===
let palette, roadColour, bC1, bC2, bgC;

function setup() {
	createCanvas(windowWidth, windowHeight);
	// noLoop() removed for animation
	noFill();
	noStroke();
	const x = random([true, false]);
	palette = [
		'#D64933',
		'#FA8334',
		'#EA9010',
		'#2D854A',
		'#14591D',
		'#3587A4',
		'#23B5D3',
		'#70587C',
		'#573280',
		'#832232',
		'#DA4167',
		'#E87461'
	];
	roadColour = "#272727";
	bgC = "#FFFBE6";
	bC1 = '#050505';
}

function dottedLine(x1, y1, x2, y2, dotSize = 5) {
	let distance = dist(x1, y1, x2, y2);
	let numDots = distance / dotSize;
	let xStep = (x2 - x1) / numDots;
	let yStep = (y2 - y1) / numDots;

	strokeWeight(dotSize);

	for (let i = 0; i < numDots; i++) {
		var x = x1 + xStep * i;
		let y = y1 + yStep * i;

		if (i % 2 === 0) {
			point(x, y);
		}
	}
}


function drawStroke(x, y, side, variant, type) {
	if (type === "road") {
		stroke(roadColour);
		strokeWeight(side / 5);
	} else {
		stroke("#fffbe6");
		strokeWeight(side / 30);
	}
	let br = side * 0.4;

	if (br > side / 2) {
		br = side / 2;
	}

	if (variant === 1) {
		//top
		line(x - side / 2, y, x - br, y);
		line(x, y - side / 2, x, y - br);
		arc(x - br, y - br, 2 * br, 2 * br, 0, HALF_PI)

		//bottom
		line(x + br, y, x + side / 2, y);
		line(x, y + br, x, y + side / 2);
		arc(x + br, y + br, 2 * br, 2 * br, PI, PI * 1.5)
	} else if (variant === 2) {
		//top
		line(x + br, y, x + side / 2, y);
		line(x, y - side / 2, x, y - br);
		arc(x + br, y - br, 2 * br, 2 * br, HALF_PI, PI);

		//bottom
		line(x - side / 2, y, x - br, y);
		line(x, y + br, x, y + side / 2);
		arc(x - br, y + br, 2 * br, 2 * br, PI * 1.5, PI * 2);
	} else if (variant === 3) {
		if (type === "road") {
			dottedLine(x - side / 2, y, x + side / 2, y, side / 15);
			strokeWeight(side / 5);
		}
		line(x, y - side / 2, x, y + side / 2);
		circle(x - side / 2, y, side / 30);
		circle(x + side / 2, y, side / 30);
	} else if (variant === 4) {
		if (type === "road") {
			dottedLine(x, y - side / 2, x, y + side / 2, side / 15);
			strokeWeight(side / 5);
		}
		line(x - side / 2, y, x + side / 2, y);
		circle(x, y - side / 2, side / 30);
		circle(x, y + side / 2, side / 30);
	} else {
		line(x, y - side / 2, x, y + side / 2);
		line(x - side / 2, y, x + side / 2, y);
	}

	noStroke();
}

function drawRoad(x, y, side, variant) {
	drawStroke(x, y, side, variant, "road");
	drawStroke(x, y, side, variant, "lines");
}

function drawBuilding(x, y, side) {
	const colour = random(palette);
	const bC2 = random(palette);
	stroke(bC1);
	fill(bC2);
	rectMode(CENTER);
	const margin = side / 20;
	const variant = random([1, 2, 3, 4]);
	const posX = x - side / 2;
	const posY = y - side / 2;

	// base square
	square(x, y, side);

	if (variant === 1) {
		line(x - side / 2, y, x + side / 2, y);
		line(x, y - side / 2, x, y + side / 2);

		stroke(colour);
		fill(bC1);

		// top left
		square(random(posX + margin, posX + side / 4 - margin), random(posY + margin, posY + side / 4 - margin), margin);
		// bottom left
		square(random(posX + margin, posX + side / 4 - margin), random(y + side / 4 + margin, y + side / 2 - margin), margin);
		// top right
		square(random(x + side / 4 + margin, x + side / 2 - margin), random(posY + margin, posY + side / 4 - margin), margin);
		// bottom right
		square(random(x + side / 4 + margin, x + side / 2 - margin), random(y + side / 4 + margin, y + side / 2 - margin), margin);

		stroke(bC1);
		fill(colour);

		square(x, y, side / 2);
	} else if (variant === 2) {
		line(x - side / 2, y - side / 2, x + side / 2, y + side / 2);
		line(x + side / 2, y - side / 2, x - side / 2, y + side / 2);

		stroke(colour);
		fill(bC1);

		square(random(x - side / 2 + margin * 4, x + side / 2 - margin * 4), random(y - side / 2 + margin * 4, y + side / 2 - margin * 4), margin * 4);

		fill(bC2);
		stroke(bC1);
	} else if (variant === 3) {
		const position = random([1, 2, 3, 4]);
		fill(colour);

		if (position === 1) {
			square(x + side / 4, y + side / 4, side / 2);

			stroke(colour);
			fill(bC1);

			square(random(x - side / 2 + margin * 4, x - margin * 4), random(y - side / 2 + margin * 4, y - margin * 4), margin * 4);

			fill(bC2);
			stroke(bC1);
		} else if (position === 2) {
			square(x - side / 4, y + side / 4, side / 2);

			stroke(colour);
			fill(bC1);

			square(random(x + margin * 4, x + side / 2 - margin * 4), random(y - side / 2 + margin * 4, y - margin * 4), margin * 4);

			fill(bC2);
			stroke(bC1);
		} else if (position === 3) {
			square(x + side / 4, y - side / 4, side / 2);

			stroke(colour);
			fill(bC1);

			square(random(x - side / 2 + margin * 4, x - margin * 4), random(y + margin * 4, y + side / 2 - margin * 4), margin * 4);

			fill(bC2);
			stroke(bC1);
		} else {
			square(x - side / 4, y - side / 4, side / 2);

			stroke(colour);
			fill(bC1);

			square(random(x + margin * 4, x + side / 2 - margin * 4), random(y + margin * 4, y + side / 2 - margin * 4), margin * 4);

			fill(bC2);
			stroke(bC1);
		}
	} else if (variant === 4) {
		var position = random([1, 2]);

		if (position === 1) {
			line(posX + side / 4, posY, posX + side / 4, posY + side);
			line(posX + side / 2, posY, posX + side / 2, posY + side);
			line(posX + 3 * side / 4, posY, posX + 3 * side / 4, posY + side);

			stroke(colour);
			fill(bC1);

			square(random(posX + margin, posX + side / 4 - margin), random(posY + margin, y + side / 2 - margin), margin);
			square(random(posX + side / 4 + margin, posX + side / 2 - margin), random(posY + margin, y + side / 2 - margin), margin);
			square(random(posX + side / 2 + margin, posX + 3 * side / 4 - margin), random(posY + margin, y + side / 2 - margin), margin);
			square(random(posX + 3 * side / 4 + margin, x + side / 2 - margin), random(posY + margin, y + side / 2 - margin), margin);

			fill(bC2);
			stroke(bC1);
		} else {
			line(posX, posY + side / 4, posX + side, posY + side / 4);
			line(posX, posY + side / 2, posX + side, posY + side / 2);
			line(posX, posY + 3 * side / 4, posX + side, posY + 3 * side / 4);

			stroke(colour);
			fill(bC1);

			square(random(posX + margin, x + side / 2 - margin), random(posY + margin, posY + side / 4 - margin), margin);
			square(random(posX + margin, x + side / 2 - margin), random(posY + side / 4 + margin, posY + side / 2 - margin), margin);
			square(random(posX + margin, x + side / 2 - margin), random(posY + side / 2 + margin, posY + 3 * side / 4 - margin), margin);
			square(random(posX + margin, x + side / 2 - margin), random(posY + 3 * side / 4 + margin, y + side / 2 - margin), margin);

			fill(bC2);
			stroke(bC1);
		}
	}

	noStroke();
	noFill();
}

function makeTile(x, y, side) {
	rectMode(CENTER);
	square(x, y, side);
	var variant = random([1, 2, 3, 4, 5]);
	drawRoad(x, y, side, variant);
}

function draw() {
	background(bgC);

	let side = max(width, height) / 8;

	for (let x = 0; x <= width + side; x += (Math.max(0.001, Math.abs(side)) || 1)) {
		for (let y = 0; y <= height + side; y += (Math.max(0.001, Math.abs(side)) || 1)) {
			makeTile(x, y, side);
		}
	}

	for (let x = side / 2; x <= width + side; x += (Math.max(0.001, Math.abs(side)) || 1)) {
		for (let y = side / 2; y <= height + side; y += (Math.max(0.001, Math.abs(side)) || 1)) {
			drawBuilding(x, y, side * random(0.4, 0.5));
		}
	}

	describe("City made of truchet tiles");
}

function mouseClicked() {
	draw();
}
